const canvas=document.getElementById('petals'),ctx=canvas.getContext('2d'),coarsePointer=matchMedia('(hover: none) and (pointer: coarse)').matches,mobilePetals=coarsePointer||innerWidth<620;let petals=[],w=0,h=0,dpr=1,petalFrame=0,lastPetalTime=performance.now(),detachTimer=1.8,pointerWind=0,resizeFrame=0;
const petalColors=['#efbdc8','#dc8fa0','#f4d0d7','#c9798c'];
function resizePetals(){const oldW=w,nextW=Math.max(1,innerWidth),nextH=Math.max(1,mobilePetals&&coarsePointer?Math.max(innerHeight,screen.height||0):innerHeight);w=nextW;h=nextH;dpr=Math.min(devicePixelRatio||1,mobilePetals?1.35:1.75);const pixelW=Math.round(w*dpr),pixelH=Math.round(h*dpr);if(canvas.width!==pixelW)canvas.width=pixelW;if(canvas.height!==pixelH)canvas.height=pixelH;canvas.style.width=w+'px';canvas.style.height=h+'px';ctx.setTransform(dpr,0,0,dpr,0,0);if(!mobilePetals){const count=Math.min(w<700?42:88,Math.floor(w/15));petals=Array.from({length:count},()=>makePetal());return}if(!petals.length){const count=Math.max(10,Math.min(15,Math.round(w/30)));petals=Array.from({length:count},()=>makePetal())}else if(oldW&&oldW!==w){const ratio=w/oldW;petals.forEach(p=>{p.x*=ratio})}}
function schedulePetalResize(){if(resizeFrame)return;resizeFrame=requestAnimationFrame(()=>{resizeFrame=0;resizePetals()})}
function makePetal(fromTop=false,source=null){if(mobilePetals){const z=.72+Math.random()*.42;return{x:Math.random()*w,y:fromTop?-24-Math.random()*70:Math.random()*h,s:4.2+Math.random()*2.2,v:13+Math.random()*14,drift:(Math.random()-.5)*7,sway:5+Math.random()*8,swayPhase:Math.random()*Math.PI*2,swaySpeed:.55+Math.random()*.45,z,rot:Math.random()*Math.PI*2,spin:(Math.random()-.5)*.7,tumble:Math.random()*Math.PI*2,tumbleSpeed:.65+Math.random()*.55,a:.3+Math.random()*.24,color:petalColors[Math.floor(Math.random()*petalColors.length)],detached:false}}const z=.45+Math.random()*1.15;return{x:source?source.x:Math.random()*w,y:source?source.y:fromTop?-30-Math.random()*120:Math.random()*h,s:(2.7+Math.random()*4.5)*z,v:(.28+Math.random()*.72)*z,drift:(Math.random()-.5)*.55,z,rot:Math.random()*Math.PI*2,spin:(Math.random()-.5)*.045,tumble:Math.random()*Math.PI*2,tumbleSpeed:.018+Math.random()*.035,a:.28+Math.random()*.58,color:petalColors[Math.floor(Math.random()*petalColors.length)],detached:!!source}}
function drawPetal(p){ctx.save();ctx.translate(p.x,p.y);ctx.rotate(p.rot);if(mobilePetals){ctx.scale(.58+.42*Math.abs(Math.cos(p.tumble)),1);ctx.globalAlpha=p.a;ctx.fillStyle=p.color;const s=p.s;ctx.beginPath();ctx.moveTo(0,s*.88);ctx.bezierCurveTo(-s*.5,s*.42,-s*.68,-s*.34,-s*.22,-s*.76);ctx.quadraticCurveTo(-s*.06,-s*.88,0,-s*.6);ctx.quadraticCurveTo(s*.06,-s*.88,s*.22,-s*.76);ctx.bezierCurveTo(s*.68,-s*.34,s*.5,s*.42,0,s*.88);ctx.closePath();ctx.fill();ctx.restore();return}ctx.scale(1,.3+Math.abs(Math.sin(p.tumble))*.7);ctx.globalAlpha=p.a*(.72+.28*Math.sin(p.tumble)*Math.sin(p.tumble));ctx.fillStyle=p.color;if(p.z>1.35){ctx.shadowColor='rgba(238,172,188,.45)';ctx.shadowBlur=5}const s=p.s;ctx.beginPath();ctx.moveTo(0,s*.82);ctx.bezierCurveTo(-s*.7,s*.28,-s*.92,-s*.38,-s*.22,-s*.73);ctx.bezierCurveTo(-s*.08,-s*.88,s*.08,-s*.88,s*.22,-s*.73);ctx.bezierCurveTo(s*.92,-s*.38,s*.7,s*.28,0,s*.82);ctx.closePath();ctx.fill();ctx.restore()}
const hero=document.querySelector('.hero');addEventListener('pointermove',e=>{if(!mobilePetals)pointerWind=(e.clientX/Math.max(w,1)-.5)*.32;if(hero){const x=(e.clientX/innerWidth-.5)*-8,y=(e.clientY/innerHeight-.5)*-5;hero.style.setProperty('--px',x+'px');hero.style.setProperty('--py',y+'px')}},{passive:true});
function animate(now){const dt=Math.min(Math.max((now-lastPetalTime)/1000,0),.05),frame=dt*60;lastPetalTime=now;petalFrame+=dt;const treeWind=window.garageSakuraWind;if(mobilePetals){const breeze=(treeWind?.direction||0)*2+(treeWind?.gust||0)*2.5;ctx.clearRect(0,0,w,h);petals.forEach((p,i)=>{p.swayPhase+=p.swaySpeed*dt;p.y+=p.v*dt;p.x+=(p.drift+Math.sin(p.swayPhase)*p.sway+breeze)*dt;p.rot+=p.spin*dt;p.tumble+=p.tumbleSpeed*dt;if(p.x<-24){p.x=-24;p.drift=Math.abs(p.drift)}else if(p.x>w+24){p.x=w+24;p.drift=-Math.abs(p.drift)}if(p.y>h+32)petals[i]=makePetal(true);drawPetal(p)});requestAnimationFrame(animate);return}const breeze=pointerWind+(treeWind?.direction||0)*.34+(treeWind?.gust||0)*.52;detachTimer-=dt;if(detachTimer<=0&&treeWind?.randomSpawnPoint){const source=treeWind.randomSpawnPoint();if(source){petals[Math.floor(Math.random()*petals.length)]=makePetal(false,source)}detachTimer=1.35+Math.random()*3.1/(1+(treeWind.gust||0)*1.8)}ctx.clearRect(0,0,w,h);petals.forEach((p,i)=>{const flutter=Math.sin(p.y*.009+p.tumble)*.3*p.z;p.y+=p.v*frame*(p.detached?.78:1);p.x+=(flutter+p.drift+breeze)*frame;p.rot+=(p.spin+Math.sin(p.tumble)*.006*(treeWind?.strength||0))*frame;p.tumble+=p.tumbleSpeed*frame;if(p.y>h+35||p.x<-45||p.x>w+45)petals[i]=makePetal(true);drawPetal(p)});requestAnimationFrame(animate)}
if(!matchMedia('(prefers-reduced-motion: reduce)').matches){resizePetals();if(mobilePetals){addEventListener('resize',schedulePetalResize,{passive:true});visualViewport?.addEventListener('resize',schedulePetalResize,{passive:true})}else addEventListener('resize',resizePetals,{passive:true});document.addEventListener('visibilitychange',()=>{lastPetalTime=performance.now()},{passive:true});requestAnimationFrame(animate)}
const observer=new IntersectionObserver(entries=>entries.forEach(e=>{if(e.isIntersecting){e.target.classList.add('is-visible');observer.unobserve(e.target)}}),{threshold:.12});document.querySelectorAll('.reveal').forEach(el=>observer.observe(el));
const booking=document.getElementById('booking'),serviceSelect=document.getElementById('serviceSelect');function goBook(service){if(service)serviceSelect.value=service;booking.scrollIntoView({behavior:'smooth'});setTimeout(()=>document.querySelector('[name=name]').focus({preventScroll:true}),650)}
document.querySelectorAll('.js-book').forEach(b=>b.addEventListener('click',e=>{e.preventDefault();goBook()}));document.querySelectorAll('.service').forEach(row=>row.querySelector('button').addEventListener('click',()=>goBook(row.dataset.service)));
const BOOKING_TIME_ZONE='Europe/Dublin';
function dateInTimeZone(date,timeZone){const parts=new Intl.DateTimeFormat('en-IE',{timeZone,year:'numeric',month:'2-digit',day:'2-digit'}).formatToParts(date),values=Object.fromEntries(parts.map(part=>[part.type,part.value]));return `${values.year}-${values.month}-${values.day}`}
const dateInput=document.getElementById('dateInput'),today=dateInTimeZone(new Date(),BOOKING_TIME_ZONE);dateInput.min=today;dateInput.value=today;
const bookingForm=document.getElementById('bookingForm'),phoneInput=bookingForm.elements.phone,formStatus=document.getElementById('formStatus');
function normalizeIrishMobile(value){const compact=value.trim().replace(/[\s().-]/g,'');let national;if(/^0\d+$/.test(compact))national=compact.slice(1);else if(/^\+353\d+$/.test(compact))national=compact.slice(4);else if(/^353\d+$/.test(compact))national=compact.slice(3);else return null;return /^(?:83|85|86|87|89)\d{7}$/.test(national)?`+353${national}`:null}
bookingForm.querySelectorAll('[required]').forEach(field=>{field.addEventListener('invalid',()=>{let message='Complete this field.';if(field.name==='name')message='Enter your name.';if(field.name==='phone')message='Enter a valid Irish mobile number, such as 087 123 4567 or +353 87 123 4567.';if(field.name==='email')message=field.validity.valueMissing?'Enter your email address.':'Enter a valid email address.';if(field.name==='date')message='Choose a booking date.';field.setCustomValidity(message)});['input','change'].forEach(eventName=>field.addEventListener(eventName,()=>field.setCustomValidity('')))})
bookingForm.addEventListener('submit',e=>{e.preventDefault();const normalizedPhone=normalizeIrishMobile(phoneInput.value);if(!normalizedPhone){phoneInput.setCustomValidity('Enter a valid Irish mobile number, such as 087 123 4567 or +353 87 123 4567.');formStatus.textContent=phoneInput.validationMessage;phoneInput.reportValidity();return}phoneInput.setCustomValidity('');phoneInput.value=normalizedPhone;formStatus.textContent='Online booking is temporarily unavailable. Please try again later.'});
document.getElementById('closeSuccess').addEventListener('click',()=>document.getElementById('success').classList.remove('is-open'));
